pub const SEARCH: &str = r#"query HomeSearch($query:String!,$after:String){search(query:$query,type:ISSUE,first:100,after:$after){issueCount pageInfo{hasNextPage endCursor} nodes{__typename ... on Issue{id title number url issueState:state updatedAt assignees(first:100){pageInfo{hasNextPage endCursor} nodes{login}} repository{nameWithOwner}} ... on PullRequest{id title number url pullRequestState:state updatedAt repository{nameWithOwner}}}}}"#;
pub const PROJECT: &str = r#"query HomeProject($id:ID!,$after:String){node(id:$id){__typename ... on ProjectV2{id title url fields(first:100,after:$after){pageInfo{hasNextPage endCursor} nodes{... on ProjectV2Field{id name dataType} ... on ProjectV2SingleSelectField{id name dataType options{id name}}}}}}}"#;
pub const ITEMS: &str = r#"query HomeItems($id:ID!,$after:String,$status:String!,$due:String!,$includeDue:Boolean!){node(id:$id){... on ProjectV2{items(first:100,after:$after){pageInfo{hasNextPage endCursor} nodes{id isArchived status:fieldValueByName(name:$status){... on ProjectV2ItemFieldSingleSelectValue{optionId name}} due:fieldValueByName(name:$due) @include(if:$includeDue){... on ProjectV2ItemFieldDateValue{date}} content{__typename ... on Issue{id title number url issueState:state updatedAt closedAt repository{nameWithOwner}} ... on PullRequest{id title number url pullRequestState:state updatedAt mergedAt repository{nameWithOwner}} ... on DraftIssue{id}}}}}}}"#;
pub const REQUESTS: &str = r#"query HomeReviewers($id:ID!,$after:String){node(id:$id){... on PullRequest{reviewRequests(first:100,after:$after){pageInfo{hasNextPage endCursor} nodes{requestedReviewer{__typename ... on User{id login} ... on Team{id slug} ... on EnterpriseTeam{id} ... on Bot{id login} ... on Mannequin{id login}}}}}}}"#;
pub const EVENTS: &str = r#"query HomeRequestTimes($id:ID!,$after:String){node(id:$id){... on PullRequest{timelineItems(first:100,after:$after,itemTypes:[REVIEW_REQUESTED_EVENT]){pageInfo{hasNextPage endCursor} nodes{... on ReviewRequestedEvent{createdAt actor{login} requestedReviewer{__typename ... on User{id login} ... on Team{id slug} ... on EnterpriseTeam{id} ... on Bot{id login} ... on Mannequin{id login}}}}}}}}"#;
pub const TEAM_MEMBER: &str = r#"query HomeTeamMembership($id:ID!,$login:String!,$after:String){node(id:$id){__typename ... on Team{members(first:100,query:$login,after:$after){pageInfo{hasNextPage endCursor} nodes{login}}} ... on EnterpriseTeam{isViewerMember}}}"#;
pub const ASSIGNEES: &str = r#"query HomeAssignees($id:ID!,$after:String){node(id:$id){... on Issue{issueState:state assignees(first:100,after:$after){pageInfo{hasNextPage endCursor} nodes{login}}}}}"#;
pub const REPOSITORY_ACCESS: &str = r#"query HomeRepositoryAccess($owner:String!,$name:String!){repository(owner:$owner,name:$name){nameWithOwner issues(first:1){totalCount} pullRequests(first:1){totalCount}}}"#;
